-- c007-v021: না তুমি-ভয়-পাবে তাদের-সামনে-থেকে কারণ– সদাপ্রভু তোমার-ঈশ্বর তোমার-মধ্যে ঈশ্বর মহান এবং–ভয়ঙ্কর
-- c007-v022: এবং–তাড়িয়ে-দেবেন সদাপ্রভু তোমার-ঈশ্বর – জাতিগুলিকে–যে এই তোমার-সামনে-থেকে অল্প অল্প না তুমি-সক্ষম-হবে শেষ-করতে-তাদের তাড়াতাড়ি পাছে– বৃদ্ধি-পায় তোমার-বিরুদ্ধে পশু মাঠের–যে
-- c007-v023: এবং–তাদের-দেবেন সদাপ্রভু তোমার-ঈশ্বর তোমার-সামনে এবং–তিনি-বিভ্রান্ত-করবেন-তাদের বিভ্রান্তি বড় যতক্ষণ-না তাদের-ধ্বংস-হয়
